#!/usr/bin/env bash
# Regenerate scip_pb2.py from scip.proto with the pinned protoc release.
#
#   regenerate.sh          write scip_pb2.py when the generated bytes differ
#   regenerate.sh --check  compare only; exit 1 when scip_pb2.py is not the
#                          pinned protoc's output for scip.proto
#
# The protoc archive is verified against the sha256 pinned below before it runs.
set -euo pipefail

PROTOC_VERSION=35.1
case "$(uname -s)-$(uname -m)" in
  Linux-x86_64)
    ASSET=linux-x86_64
    SHA256=6930ebf62bd4ea607b98fff052596c6ee564b9835b4ce172c75a3f53ae9d91b7
    ;;
  Linux-aarch64 | Linux-arm64)
    ASSET=linux-aarch_64
    SHA256=01bf9d08808c7f96678b63f4bd8efa559bb4f83d5a7a270d5edaf507f9d5d9cf
    ;;
  Darwin-arm64)
    ASSET=osx-aarch_64
    SHA256=193289af0470c6a1aada357d4fba0bbf8d78bfaac8b5e42ca30af2ef75583de2
    ;;
  Darwin-x86_64)
    ASSET=osx-x86_64
    SHA256=537d73604a344ded6fc94e98e07e529d4fe3e4a0b09e59905353950fafc2a1f7
    ;;
  *)
    echo "no pinned protoc ${PROTOC_VERSION} for $(uname -sm)" >&2
    exit 2
    ;;
esac

CHECK=0
[[ "${1:-}" == "--check" ]] && CHECK=1
VENDOR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYTHON=${PYTHON:-python3}
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

URL="https://github.com/protocolbuffers/protobuf/releases/download/v${PROTOC_VERSION}/protoc-${PROTOC_VERSION}-${ASSET}.zip"
curl -sSfL -o "$WORK/protoc.zip" "$URL"
GOT=$("$PYTHON" -c 'import hashlib,sys;print(hashlib.sha256(open(sys.argv[1],"rb").read()).hexdigest())' "$WORK/protoc.zip")
if [[ "$GOT" != "$SHA256" ]]; then
  echo "protoc archive sha256 mismatch: got $GOT, pinned $SHA256 ($URL)" >&2
  exit 2
fi
"$PYTHON" -m zipfile -e "$WORK/protoc.zip" "$WORK/protoc"
chmod +x "$WORK/protoc/bin/protoc"
mkdir "$WORK/out"
"$WORK/protoc/bin/protoc" -I "$VENDOR" --python_out="$WORK/out" "$VENDOR/scip.proto"

if cmp -s "$WORK/out/scip_pb2.py" "$VENDOR/scip_pb2.py"; then
  echo "scip_pb2.py is current (protoc ${PROTOC_VERSION})"
  exit 0
fi
if ((CHECK)); then
  echo "scip_pb2.py differs from protoc ${PROTOC_VERSION} output; run $0" >&2
  exit 1
fi
cp "$WORK/out/scip_pb2.py" "$VENDOR/scip_pb2.py"
echo "wrote scip_pb2.py (protoc ${PROTOC_VERSION})"
